import javax.crypto.Mac
import javax.crypto.spec.SecretKeySpec
import java.util.Base64
import java.security.{KeyPairGenerator, PublicKey, PrivateKey, Signature}
import java.nio.charset.StandardCharsets
import scala.util.{Try, Success, Failure}
import java.util.concurrent.ConcurrentHashMap
import java.time.Instant

object TokenService {
  private val hmacSecret = "super_secret_key_for_hmac_signing_2024".getBytes(StandardCharsets.UTF_8)
  private val keyPair = {
    val gen = KeyPairGenerator.getInstance("RSA")
    gen.initialize(2048)
    gen.generateKeyPair()
  }
  private val publicKey: PublicKey = keyPair.getPublic
  private val privateKey: PrivateKey = keyPair.getPrivate
  private val sessions = new ConcurrentHashMap[String, SessionData]()
  private val revokedTokens = new ConcurrentHashMap[String, Long]()

  case class SessionData(userId: String, role: String, createdAt: Long, lastAccess: Long)
  case class TokenHeader(alg: String, typ: String)
  case class TokenPayload(sub: String, role: String, iat: Long, exp: Long, jti: String)
  case class VerifiedToken(header: TokenHeader, payload: TokenPayload)

  def base64UrlEncode(data: Array[Byte]): String =
    Base64.getUrlEncoder.withoutPadding.encodeToString(data)

  def base64UrlDecode(s: String): Array[Byte] =
    Base64.getUrlDecoder.decode(s)

  def parseHeader(headerB64: String): Option[TokenHeader] = Try {
    val json = new String(base64UrlDecode(headerB64), StandardCharsets.UTF_8)
    val algPattern = """"alg"\s*:\s*"([^"]+)"""".r
    val typPattern = """"typ"\s*:\s*"([^"]+)"""".r
    val alg = algPattern.findFirstMatchIn(json).map(_.group(1)).getOrElse("")
    val typ = typPattern.findFirstMatchIn(json).map(_.group(1)).getOrElse("")
    TokenHeader(alg, typ)
  }.toOption

  def parsePayload(payloadB64: String): Option[TokenPayload] = Try {
    val json = new String(base64UrlDecode(payloadB64), StandardCharsets.UTF_8)
    val subPattern = """"sub"\s*:\s*"([^"]+)"""".r
    val rolePattern = """"role"\s*:\s*"([^"]+)"""".r
    val iatPattern = """"iat"\s*:\s*(\d+)""".r
    val expPattern = """"exp"\s*:\s*(\d+)""".r
    val jtiPattern = """"jti"\s*:\s*"([^"]+)"""".r
    val sub = subPattern.findFirstMatchIn(json).map(_.group(1)).getOrElse("")
    val role = rolePattern.findFirstMatchIn(json).map(_.group(1)).getOrElse("")
    val iat = iatPattern.findFirstMatchIn(json).map(_.group(1).toLong).getOrElse(0L)
    val exp = expPattern.findFirstMatchIn(json).map(_.group(1).toLong).getOrElse(0L)
    val jti = jtiPattern.findFirstMatchIn(json).map(_.group(1)).getOrElse("")
    TokenPayload(sub, role, iat, exp, jti)
  }.toOption

  def computeHmac(data: String): Array[Byte] = {
    val mac = Mac.getInstance("HmacSHA256")
    mac.init(new SecretKeySpec(hmacSecret, "HmacSHA256"))
    mac.doFinal(data.getBytes(StandardCharsets.UTF_8))
  }

  def verifyRsaSignature(data: String, signatureBytes: Array[Byte]): Boolean = {
    val sig = Signature.getInstance("SHA256withRSA")
    sig.initVerify(publicKey)
    sig.update(data.getBytes(StandardCharsets.UTF_8))
    sig.verify(signatureBytes)
  }

  def constantTimeEquals(a: Array[Byte], b: Array[Byte]): Boolean = {
    if (a.length != b.length) return false
    var result = 0
    var i = 0
    while (i < a.length) {
      result |= (a(i) ^ b(i))
      i += 1
    }
    result == 0
  }

  def verifySignature(header: TokenHeader, signingInput: String, signature: Array[Byte]): Boolean = {
    header.alg match {
      case "HS256" =>
        val expected = computeHmac(signingInput)
        constantTimeEquals(expected, signature)
      case "RS256" =>
        verifyRsaSignature(signingInput, signature)
      case "none" =>
        signature.isEmpty
      case _ => false
    }
  }

  def isTokenRevoked(jti: String): Boolean = {
    revokedTokens.containsKey(jti)
  }

  def isTokenExpired(exp: Long): Boolean = {
    Instant.now.getEpochSecond > exp
  }

  def validateToken(tokenString: String): Either[String, VerifiedToken] = {
    val parts = tokenString.split("\\.")
    if (parts.length != 3) return Left("Invalid token format")

    val headerB64 = parts(0)
    val payloadB64 = parts(1)
    val signatureB64 = parts(2)

    val header = parseHeader(headerB64) match {
      case Some(h) => h
      case None => return Left("Invalid header")
    }

    val payload = parsePayload(payloadB64) match {
      case Some(p) => p
      case None => return Left("Invalid payload")
    }

    val signingInput = s"$headerB64.$payloadB64"
    val signature = Try(base64UrlDecode(signatureB64)).getOrElse(Array.empty[Byte])

    if (!verifySignature(header, signingInput, signature)) {
      return Left("Invalid signature")
    }

    if (isTokenRevoked(payload.jti)) {
      return Left("Token revoked")
    }

    if (isTokenExpired(payload.exp)) {
      return Left("Token expired")
    }

    Right(VerifiedToken(header, payload))
  }

  def createSession(token: VerifiedToken): String = {
    val sessionId = java.util.UUID.randomUUID().toString
    val session = SessionData(
      userId = token.payload.sub,
      role = token.payload.role,
      createdAt = Instant.now.getEpochSecond,
      lastAccess = Instant.now.getEpochSecond
    )
    sessions.put(sessionId, session)
    sessionId
  }

  def authorize(sessionId: String, requiredRole: String): Boolean = {
    val session = sessions.get(sessionId)
    if (session == null) return false
    val now = Instant.now.getEpochSecond
    if (now - session.lastAccess > 3600) {
      sessions.remove(sessionId)
      return false
    }
    sessions.put(sessionId, session.copy(lastAccess = now))
    session.role == requiredRole || session.role == "admin"
  }

  def revokeToken(jti: String): Unit = {
    revokedTokens.put(jti, Instant.now.getEpochSecond)
  }

  def issueToken(userId: String, role: String, algorithm: String = "HS256"): String = {
    val now = Instant.now.getEpochSecond
    val jti = java.util.UUID.randomUUID().toString
    val headerJson = s"""{"alg":"$algorithm","typ":"JWT"}"""
    val payloadJson = s"""{"sub":"$userId","role":"$role","iat":$now,"exp":${now + 3600},"jti":"$jti"}"""
    val headerB64 = base64UrlEncode(headerJson.getBytes(StandardCharsets.UTF_8))
    val payloadB64 = base64UrlEncode(payloadJson.getBytes(StandardCharsets.UTF_8))
    val signingInput = s"$headerB64.$payloadB64"

    val signature = algorithm match {
      case "HS256" => computeHmac(signingInput)
      case "RS256" =>
        val sig = Signature.getInstance("SHA256withRSA")
        sig.initSign(privateKey)
        sig.update(signingInput.getBytes(StandardCharsets.UTF_8))
        sig.sign()
      case _ => Array.empty[Byte]
    }

    s"$headerB64.$payloadB64.${base64UrlEncode(signature)}"
  }

  def main(args: Array[String]): Unit = {
    val token = issueToken("user123", "user")
    println(s"Issued token: $token")

    validateToken(token) match {
      case Right(verified) =>
        val sessionId = createSession(verified)
        println(s"Session created: $sessionId")
        println(s"Authorized as user: ${authorize(sessionId, \"user\")}")
        println(s"Authorized as admin: ${authorize(sessionId, \"admin\")}")
      case Left(error) =>
        println(s"Validation failed: $error")
    }
  }
}
